+import subprocess
+from pathlib import Path
+
+import pytest
+
+ROOT = Path(__file__).resolve().parent.parent
+APP_JS = ROOT / "web" / "app.js"
+HARNESS = Path(__file__).resolve().parent / "web" / "create_delete_harness.js"
+
+NODE = shutil.which("node")
