+)
+
+SANDBOX = "D:\\WorkSpace\\FilePilot\\Sandbox"
+
+
+@pytest.fixture(scope="module")
+def results():
+    proc = subprocess.run(
+        [NODE, str(HARNESS), str(APP_JS)],
+        capture_output=True, text=True, timeout=120,
+    )
+    assert proc.returncode == 0, f"harness failed: {proc.stderr}"
+    return json.loads(proc.stdout.strip().splitlines()[-1])
+
+
+def _posts(res):
+    return [(p["url"], p["body"]) for p in res["posts"]]
+
+
+def test_row_action_opens_prefilled_dialog(results):
+    r = results["rename_dialog"]
+    assert r["has_action_button"] is True
+    assert r["action_title"] == "Rename"
+    assert r["action_aria"] == "Rename a.txt"
+    assert r["dialog_open"] is True
+    assert r["title"] == "Rename file"
+    assert r["sub"] == "in " + SANDBOX
+    assert r["input_value"] == "a.txt"
+    assert r["confirm_label"] == "Rename"
+    # Prefilled with the current name: nothing to submit yet.
+    assert r["confirm_disabled"] is True
+    assert r["chips_hidden"] is True
+    assert r["card_hidden"] is True
+    assert r["viewer_calls"] == 0
+    assert r["posts"] == []
+
+
+def test_confirm_posts_exact_path_and_name(results):
